<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { qualityApi } from '../../api/quality.api'
import type { QualityInspectionPreview, QualityPunishRule, ReasonGroup, SupplierFlowerItem } from '../../models/quality'
import WareState from '@/shared/components/WareState.vue'
import WareStatus from '@/shared/components/WareStatus.vue'
import { sessionStore } from '@/store/session'
import { appConfig } from '@/app/config/env'

const item = ref<SupplierFlowerItem | null>(null)
const supplierName = ref('')
const loading = ref(true)
const error = ref('')
const selectedUnits = ref<number[]>([])
const reasonGroups = ref<ReasonGroup[]>([])
const selectedReasonIds = ref<number[]>([])
const operation = ref(0)
const submitting = ref(false)
const dutyDrawerVisible = ref(false)
const dutyRemark = ref('')
const dutyMedia = ref<string[]>([])
const mediaUploading = ref(false)
const dutySubmitting = ref(false)
const inspectionConfirmVisible = ref(false)
const inspectionPreview = ref<QualityInspectionPreview | null>(null)
const previewLoading = ref(false)
const operationPickerVisible = ref(false)
const reasonPickerVisible = ref(false)
const customerChoiceVisible = ref(false)
const inspectionMedia = ref<string[]>([])
const inspectionMediaUploading = ref(false)
const allowDowngradeRestock = ref(false)
const punishRulesVisible = ref(false)
const punishRulesLoading = ref(false)
const punishRules = ref<QualityPunishRule[]>([])
const punishRulesError = ref('')
const dispositionHelpVisible = ref(false)
const operations = [
  { id: 1, label: '降一级', description: '花材保留，将当前等级下调一级后继续流转。' },
  { id: 2, label: '降两级', description: '花材保留，将当前等级下调两级后继续流转。' },
  { id: 3, label: '退货不补', description: '问题花材退回供应商，不再发起补货。' },
  { id: 5, label: '退货补货', description: '问题花材退回供应商，同时形成补货需求。' },
  { id: 6, label: '缺货补货', description: '确认供应商缺货，并形成对应数量的补货需求。' },
  { id: 7, label: '缺货不补', description: '确认供应商缺货，但不再发起补货。' },
  { id: 12, label: '换货', description: '按换货方式处理，后续进入换货业务流程。' },
]
const selectedReasons = computed(() => reasonGroups.value.flatMap(group => group.reasons).filter(reason => selectedReasonIds.value.includes(reason.id)))
const punishRuleMap = computed(() => new Map(punishRules.value.map(rule => [rule.operation, rule])))
const allSelected = computed(() => !!item.value && selectedUnits.value.length === item.value.quantity)
const unitMarkMap = computed(() => new Map((item.value?.unitMarks ?? []).map(mark => [mark.unit, mark.operation])))
const operationLabels: Record<number, string> = { 1: '降一级', 2: '降两级', 3: '退货不补', 5: '退货补货', 6: '缺货补货', 7: '缺货不补', 12: '换货' }
const revocableSelectedCount = computed(() => selectedUnits.value.filter(unit => unitMarkMap.value.has(unit)).length)
const canSubmitInspection = computed(() => selectedUnits.value.length > 0 && !previewLoading.value && !submitting.value && sessionStore.can('quality.submit'))
const submitLabel = computed(() => {
  if (submitting.value) return '正在提交…'
  if (!selectedUnits.value.length) return '请先选择花材'
  return `标记所选 ${selectedUnits.value.length} 扎`
})
const gradeResult = computed(() => {
  if (!inspectionPreview.value || ![1, 2].includes(inspectionPreview.value.operation)) return ''
  const grades = ['A级', 'B级', 'C级', 'D级', 'E级']
  const currentIndex = grades.indexOf(inspectionPreview.value.grade)
  if (currentIndex < 0) return ''
  const downgradeLevels = inspectionPreview.value.operation === 2 ? 2 : 1
  return grades[Math.min(currentIndex + downgradeLevels, grades.length - 1)]
})
function unitOperation(unit: number) { return unitMarkMap.value.get(unit) }
function unitOperationLabel(unit: number) { const value = unitOperation(unit); return value ? operationLabels[value] || '已标记' : '' }
function unitTone(unit: number) { const value = unitOperation(unit); return [6, 7].includes(value ?? 0) ? 'shortage' : [3, 5].includes(value ?? 0) ? 'return' : [1, 2].includes(value ?? 0) ? 'downgrade' : value === 12 ? 'exchange' : '' }

async function load(id: number) {
  loading.value = true; error.value = ''
  try { [item.value, reasonGroups.value] = await Promise.all([qualityApi.getSupplierItem(id), qualityApi.getReasons()]) }
  catch (cause) { error.value = cause instanceof Error ? cause.message : '花材信息加载失败' }
  finally { loading.value = false }
}
function toggleUnit(unit: number) { const index = selectedUnits.value.indexOf(unit); index >= 0 ? selectedUnits.value.splice(index, 1) : selectedUnits.value.push(unit) }
function selectByOperations(operations: number[]) { selectedUnits.value = [...new Set((item.value?.unitMarks ?? []).filter(mark => operations.includes(mark.operation)).map(mark => mark.unit))] }
function toggleAllUnits() { if (!item.value) return; selectedUnits.value = allSelected.value ? [] : Array.from({ length: item.value.quantity }, (_, index) => index + 1) }
function openOperationLogs() { if (item.value) uni.navigateTo({ url: `/features/quality/pages/operation-log/index?id=${item.value.id}` }) }
function toggleReason(id: number) { const index = selectedReasonIds.value.indexOf(id); if (index >= 0) selectedReasonIds.value.splice(index, 1); else if (selectedReasonIds.value.length >= 10) uni.showToast({ title: '最多选择10个质检问题', icon: 'none' }); else selectedReasonIds.value.push(id) }
function callPhone(phone?: string | null) {
  const phoneNumber = String(phone || '').replace(/[^\d+]/g, '')
  if (!phoneNumber) return uni.showToast({ title: '暂无可拨打的手机号', icon: 'none' })
  // #ifdef H5
  window.location.href = `tel:${phoneNumber}`
  // #endif
  // #ifndef H5
  uni.makePhoneCall({ phoneNumber, fail: () => uni.showToast({ title: '无法唤起拨号，请稍后重试', icon: 'none' }) })
  // #endif
}
async function saveControl(command: { limitDistribution?: boolean; merchantResponsibility?: boolean; noAfterSale?: boolean; remark?: string; media?: string[] }): Promise<boolean> {
  if (!item.value || !sessionStore.can('quality.itemControl')) { uni.showToast({ title: '当前账户没有花材控制权限', icon: 'none' }); return false }
  try { await qualityApi.updateSupplierItemControls(item.value.id, command); item.value = await qualityApi.getSupplierItem(item.value.id); uni.showToast({ title: '设置已更新', icon: 'success' }); return true }
  catch (cause) { uni.showToast({ title: cause instanceof Error ? cause.message : '设置失败', icon: 'none' }); return false }
}
function changeLimit(value: boolean) { uni.showModal({ title: value ? '限制配货' : '取消限制配货', content: value ? '开启后，该货架花材将限制配货，确认继续？' : '确认恢复该货架花材配货？', confirmColor: value ? '#C93636' : '#0F766E', success: ({ confirm }) => confirm ? saveControl({ limitDistribution: value }) : undefined }) }
function changeResponsibility(value: boolean) {
  if (!value) return uni.showModal({ title: '取消商家全责', content: '确认取消该花材的商家全责标记及凭证？', success: ({ confirm }) => confirm ? saveControl({ merchantResponsibility: false, remark: '', media: [] }) : undefined })
  dutyRemark.value = item.value?.controls.responsibilityRemark ?? ''
  dutyMedia.value = [...(item.value?.controls.responsibilityMedia ?? [])]
  dutyDrawerVisible.value = true
}
function changeNoAfterSale(value: boolean) { uni.showModal({ title: value ? '设置顾客不售后' : '恢复顾客售后', content: value ? '该操作会影响顾客售后权益，确认继续？' : '确认恢复该花材的顾客售后？', confirmColor: value ? '#C93636' : '#0F766E', success: ({ confirm }) => confirm ? saveControl({ noAfterSale: value }) : undefined }) }
function mediaUrl(url: string) { return url.startsWith('http') ? url : `${appConfig.apiBaseUrl.replace(/\/api\/?$/, '')}${url}` }
function isVideo(url: string) { return /\.(mp4|mov)(\?|$)/i.test(url) }
async function uploadPaths(paths: string[]) {
  if (!item.value || !paths.length) return
  mediaUploading.value = true
  try { for (const path of paths) dutyMedia.value.push((await qualityApi.uploadSupplierItemMedia(item.value.id, path)).url) }
  catch (cause) { uni.showToast({ title: cause instanceof Error ? cause.message : '上传失败', icon: 'none' }) }
  finally { mediaUploading.value = false }
}
function chooseImages() {
  const remaining = 6 - dutyMedia.value.length
  if (remaining <= 0) return uni.showToast({ title: '最多上传6个文件', icon: 'none' })
  uni.chooseImage({ count: remaining, sourceType: ['album', 'camera'], success: result => uploadPaths(Array.isArray(result.tempFilePaths) ? result.tempFilePaths : [result.tempFilePaths]) })
}
function chooseVideo() {
  if (dutyMedia.value.length >= 6) return uni.showToast({ title: '最多上传6个文件', icon: 'none' })
  uni.chooseVideo({ sourceType: ['album', 'camera'], compressed: true, success: result => uploadPaths([result.tempFilePath]) })
}
function removeDutyMedia(index: number) { if (!mediaUploading.value) dutyMedia.value.splice(index, 1) }
function previewDutyImage(url: string) { uni.previewImage({ current: mediaUrl(url), urls: dutyMedia.value.filter(value => !isVideo(value)).map(mediaUrl) }) }
function previewInspectionImage(url: string) { uni.previewImage({ current: mediaUrl(url), urls: inspectionMedia.value.filter(value => !isVideo(value)).map(mediaUrl) }) }
async function uploadInspectionPaths(paths: string[]) {
  if (!item.value || !paths.length) return
  inspectionMediaUploading.value = true
  try { for (const path of paths) inspectionMedia.value.push((await qualityApi.uploadSupplierItemMedia(item.value.id, path)).url) }
  catch (cause) { uni.showToast({ title: cause instanceof Error ? cause.message : '上传失败', icon: 'none' }) }
  finally { inspectionMediaUploading.value = false }
}
function chooseInspectionMedia() {
  const remaining = 6 - inspectionMedia.value.length
  if (remaining <= 0) return uni.showToast({ title: '图片和视频合计最多6个', icon: 'none' })
  uni.showActionSheet({ itemList: ['拍摄/选择图片', '拍摄/选择视频'], success: ({ tapIndex }) => {
    if (tapIndex === 0) uni.chooseImage({ count: remaining, sourceType: ['album', 'camera'], success: result => uploadInspectionPaths(Array.isArray(result.tempFilePaths) ? result.tempFilePaths : [result.tempFilePaths]) })
    else uni.chooseVideo({ sourceType: ['album', 'camera'], compressed: true, success: result => uploadInspectionPaths([result.tempFilePath]) })
  } })
}
function removeInspectionMedia(index: number) { if (!inspectionMediaUploading.value) inspectionMedia.value.splice(index, 1) }
async function loadPunishRules() {
  if (punishRules.value.length || punishRulesLoading.value) return
  punishRulesLoading.value = true; punishRulesError.value = ''
  try { punishRules.value = await qualityApi.getPunishRules() }
  catch (cause) { punishRulesError.value = cause instanceof Error ? cause.message : '处罚说明加载失败' }
  finally { punishRulesLoading.value = false }
}
function openPunishRules() { punishRulesVisible.value = true; loadPunishRules() }
function openDispositionHelp() { dispositionHelpVisible.value = true; loadPunishRules() }
function closeDutyDrawer() { if (!mediaUploading.value && !dutySubmitting.value) dutyDrawerVisible.value = false }
async function submitResponsibility() {
  if (!dutyMedia.value.length) return uni.showToast({ title: '请至少上传1个图片或视频', icon: 'none' })
  if (!dutyRemark.value.trim()) return uni.showToast({ title: '请填写判责备注', icon: 'none' })
  dutySubmitting.value = true
  const saved = await saveControl({ merchantResponsibility: true, remark: dutyRemark.value.trim(), media: dutyMedia.value })
  dutySubmitting.value = false
  if (saved) dutyDrawerVisible.value = false
}
async function openInspectionConfirm() {
  if (!item.value || !sessionStore.can('quality.submit')) return
  if (!selectedReasonIds.value.length) return uni.showToast({ title: '请选择具体质检问题', icon: 'none' })
  previewLoading.value = true
  try {
    inspectionPreview.value = await qualityApi.getInspectionPreview(item.value.id, { affectedUnits: selectedUnits.value, reasonIds: selectedReasonIds.value, operation: operation.value })
    reasonPickerVisible.value = false
    inspectionConfirmVisible.value = true
  } catch (cause) { uni.showToast({ title: cause instanceof Error ? cause.message : '处罚信息加载失败', icon: 'none' }) }
  finally { previewLoading.value = false }
}
function closeInspectionConfirm() { if (!submitting.value && !inspectionMediaUploading.value) inspectionConfirmVisible.value = false }
function openOperationPicker() {
  if (!selectedUnits.value.length) return uni.showToast({ title: '请选择存在问题的花材扎号', icon: 'none' })
  operationPickerVisible.value = true
}
function closeOperationPicker() { operationPickerVisible.value = false }
function confirmOperation() {
  if (!operation.value) return uni.showToast({ title: '请选择处置方式', icon: 'none' })
  operationPickerVisible.value = false
  reasonPickerVisible.value = true
}
function openReasonPicker() {
  if (!selectedUnits.value.length) return uni.showToast({ title: '请选择存在问题的花材扎号', icon: 'none' })
  if (!operation.value) return uni.showToast({ title: '请选择处置方式', icon: 'none' })
  inspectionConfirmVisible.value = false
  reasonPickerVisible.value = true
}
function closeReasonPicker() { if (!previewLoading.value) reasonPickerVisible.value = false }
function changeAllocation(allocated:boolean){if(!item.value||!selectedUnits.value.length)return uni.showToast({title:'请先选择花材扎号',icon:'none'});uni.showModal({title:allocated?'确认配货':'确认取消配货',content:`将对选中的${selectedUnits.value.length}扎花材执行${allocated?'配货':'取消配货'}，确认继续？`,success:async({confirm})=>{if(!confirm||!item.value)return;try{await qualityApi.setUnitAllocation(item.value.id,selectedUnits.value,allocated);item.value=await qualityApi.getSupplierItem(item.value.id);selectedUnits.value=[];uni.showToast({title:allocated?'配货成功':'已取消配货',icon:'success'})}catch(cause){uni.showToast({title:cause instanceof Error?cause.message:'操作失败',icon:'none'})}}})}
function orderRestock(){if(!selectedUnits.value.length)return uni.showToast({title:'请先选择花材扎号',icon:'none'});uni.showToast({title:'下单补货功能待接入补货业务',icon:'none'})}
function revokeSelected(){if(!item.value||!selectedUnits.value.length)return uni.showToast({title:'请选择已标记质检问题的花材',icon:'none'});const marked=selectedUnits.value.filter(unit=>unitMarkMap.value.has(unit));if(!marked.length)return uni.showToast({title:'所选花材没有质检问题标记',icon:'none'});uni.showModal({title:'撤销质检问题',content:`仅撤销${marked.length}扎花材的质检问题标记，配货状态不会改变。`,confirmColor:'#C93636',success:async({confirm})=>{if(!confirm||!item.value)return;try{await qualityApi.revokeInspection(item.value.id,marked);item.value=await qualityApi.getSupplierItem(item.value.id);selectedUnits.value=[];uni.showToast({title:'质检标记已撤销',icon:'success'})}catch(cause){uni.showToast({title:cause instanceof Error?cause.message:'撤销失败',icon:'none'})}}})}
async function submit() {
  if (!item.value || !sessionStore.can('quality.submit')) return
  if (!selectedUnits.value.length) return uni.showToast({ title: '请选择存在问题的花材扎号', icon: 'none' })
  if (!selectedReasonIds.value.length) return uni.showToast({ title: '请选择具体质检问题', icon: 'none' })
  if (!operation.value) return uni.showToast({ title: '请选择处置方式', icon: 'none' })
  submitting.value = true
  try { await qualityApi.inspectSupplierItem(item.value.id, { status: 10, affectedUnits: selectedUnits.value, reasonIds: selectedReasonIds.value, operation: operation.value, evidenceMedia: inspectionMedia.value, allowDowngradeRestock: [5, 6].includes(operation.value) && allowDowngradeRestock.value }); inspectionConfirmVisible.value = false; uni.showToast({ title: '质检问题已标记', icon: 'success' }); setTimeout(() => uni.navigateBack(), 500) }
  catch (cause) { uni.showToast({ title: cause instanceof Error ? cause.message : '提交失败', icon: 'none' }) } finally { submitting.value = false }
}
onLoad(query => { supplierName.value = decodeURIComponent(String(query?.supplier || '')); const id = Number(query?.id); if (Number.isInteger(id) && id > 0) load(id); else { loading.value = false; error.value = '货架花材编号无效' } })
</script>

<template>
  <view class="page"><WareState v-if="loading" type="loading" title="正在加载花材" /><WareState v-else-if="error" type="error" title="加载失败" :description="error" /><template v-else-if="item">
    <view class="object-card"><view class="top"><text class="shelf">{{ item.shelf }}</text><WareStatus :tone="item.qualityStatus===0?'neutral':item.qualityStatus===1?'success':'danger'" :label="item.qualityStatusLabel" /></view></view>
    <view class="relation-card">
      <view class="party supplier-party"><view class="party-name-line"><text class="party-tag">商</text><text class="party-name">{{ item.supplier.name || supplierName }}</text></view><text class="party-phone" @click="callPhone(item.supplier.phone)">{{ item.supplier.phone || '未留手机号' }}</text></view>
      <view class="party customer-party"><template v-if="item.customer"><view class="party-name-line"><text class="party-tag customer-tag">客</text><text class="channel-badge">繁花</text><text class="party-name">{{ item.customer.name || '未命名客户' }}</text></view><text class="party-phone" @click="callPhone(item.customer.phone)">{{ item.customer.phone || '未留手机号' }}</text></template><template v-else><view class="party-name-line"><text class="party-tag customer-tag">客</text></view><text class="empty-customer">暂无关联客户</text></template></view>
      <view class="marker-panel"><view class="marker-head"><text>业务标记</text><view class="marker-head-actions"><text v-if="item.customer" class="customer-choice" @click="customerChoiceVisible=true">客户诉求：{{ item.customer.unqualifiedWayLabel }}</text><text v-if="item.controls.merchantResponsibility" class="marker-detail" @click="changeResponsibility(true)">查看详情</text></view></view><view class="marker-list"><view :class="['marker-chip','danger',{active:item.controls.merchantResponsibility}]" @click="changeResponsibility(!item.controls.merchantResponsibility)"><text class="marker-state">{{ item.controls.merchantResponsibility ? '✓' : '' }}</text><text>商家全责</text></view><view :class="['marker-chip',{active:item.controls.limitDistribution}]" @click="changeLimit(!item.controls.limitDistribution)"><text class="marker-state">{{ item.controls.limitDistribution ? '✓' : '' }}</text><text>限制配货</text></view><view :class="['marker-chip','danger',{active:item.controls.noAfterSale}]" @click="changeNoAfterSale(!item.controls.noAfterSale)"><text class="marker-state">{{ item.controls.noAfterSale ? '✓' : '' }}</text><text>顾客不售后</text></view></view></view>
    </view>
    <view class="operation"><view class="operation-title"><view><text class="section-title">{{ item.flowerName }} · {{ item.grade }}</text><text class="operation-subtitle">成熟度：{{ item.maturity || '未设置' }}　规格：{{ item.bundleSpecification || '未设置' }}</text></view><button class="log-entry" @click="openOperationLogs">操作日志</button></view>
        <view class="quick-select"><view class="detail-heading"><text>花材明细</text><text>已选 {{ selectedUnits.length }} 扎</text></view><view class="batch-actions"><button @click="selectByOperations([6,7])">选择缺货项</button><button @click="selectByOperations([3,5])">选择退货项</button><button @click="toggleAllUnits">{{ allSelected ? '清空选择' : '全选可操作项' }}</button></view></view>
        <view class="unit-grid"><view v-for="unit in item.quantity" :key="unit" :class="['unit-item',unitTone(unit),{selected:selectedUnits.includes(unit),marked:unitOperation(unit),allocated:item.allocatedUnits?.includes(unit)}]" @click="toggleUnit(unit)"><text v-if="selectedUnits.includes(unit)" class="unit-check">✓</text><text class="unit-number">{{ String(unit).padStart(4,'0') }}</text><text v-if="unitOperation(unit)" class="unit-mark">{{ unitOperationLabel(unit) }}</text><text v-else-if="item.allocatedUnits?.includes(unit)" class="unit-mark">已配货</text><text v-else class="unit-mark normal">待处理</text></view></view>
      <view class="action-dock">
        <view class="frequent-actions"><view class="frequent-head"><text>快捷作业</text><text>作用于已选花材</text></view><view class="allocation-actions"><button class="restock-order" @click="orderRestock">下单补货</button><button @click="changeAllocation(true)">配货</button><button @click="changeAllocation(false)">取消配货</button></view></view>
        <view class="submit-segment"><button class="revoke-button" :disabled="!revocableSelectedCount" @click="revokeSelected">撤销所选标记</button><button class="submit" :loading="previewLoading || submitting" :disabled="!canSubmitInspection" @click="openOperationPicker">{{ submitLabel }}</button></view>
      </view>
    </view>
  </template>
    <view v-if="customerChoiceVisible && item?.customer" class="choice-mask" @click="customerChoiceVisible=false">
      <view class="choice-dialog" @click.stop>
        <text class="choice-title">客户质检选择</text>
        <view class="choice-message"><text>存在质检问题时，客户选择</text><text class="choice-emphasis">{{ item.customer.unqualifiedWayLabel }}</text><text>。</text></view>
        <button @click="customerChoiceVisible=false">我知道了</button>
      </view>
    </view>
    <view v-if="dutyDrawerVisible" class="drawer-mask" @click="closeDutyDrawer">
      <view class="duty-drawer" @click.stop>
        <view class="drawer-handle"></view>
        <view class="drawer-head"><view><text class="drawer-title">设置商家全责</text><text class="drawer-desc">上传现场凭证并填写判责备注</text></view><text class="drawer-close" @click="closeDutyDrawer">×</text></view>
        <view class="field-head"><text>图片/视频 *</text><text>{{ dutyMedia.length }}/6</text></view>
        <view class="media-grid">
          <view v-for="(media,index) in dutyMedia" :key="media" class="media-item">
            <video v-if="isVideo(media)" :src="mediaUrl(media)" class="media-preview" controls object-fit="cover" />
            <image v-else :src="mediaUrl(media)" class="media-preview" mode="aspectFill" @click="previewDutyImage(media)" />
            <text class="media-remove" @click="removeDutyMedia(index)">×</text>
          </view>
          <view v-if="dutyMedia.length<6" class="media-add" @click="chooseImages"><text class="add-icon">＋</text><text>图片</text></view>
          <view v-if="dutyMedia.length<6" class="media-add" @click="chooseVideo"><text class="video-icon">▶</text><text>视频</text></view>
        </view>
        <text v-if="mediaUploading" class="upload-status">正在上传，请稍候…</text>
        <view class="field-head remark-head"><text>判责备注 *</text><text>{{ dutyRemark.length }}/300</text></view>
        <textarea v-model="dutyRemark" class="duty-textarea" maxlength="300" placeholder="说明现场情况及判责依据" />
        <button class="duty-submit" :loading="dutySubmitting" :disabled="mediaUploading || dutySubmitting" @click="submitResponsibility">确认设置</button>
      </view>
    </view>
    <view v-if="operationPickerVisible" class="drawer-mask operation-picker-mask" @click="closeOperationPicker">
